"""Totals for the bakery's sales log (a CSV file with date and amount columns)."""
import csv
from datetime import date, timedelta


def load_rows(path):
    """Return a list of (date, amount) tuples."""
    rows = []
    with open(path, newline="") as fh:
        for rec in csv.DictReader(fh):
            rows.append((date.fromisoformat(rec["date"]), float(rec["amount"])))
    return rows


def totals_by_month(rows):
    """Total takings per month, keyed like YYYY-MM."""
    totals = {}
    for day, amount in rows:
        key = day.strftime("%Y-%m")
        totals[key] = round(totals.get(key, 0.0) + amount, 2)
    return totals


def totals_by_week(rows):
    """Total takings per week, keyed by the date the week starts on, written YYYY-MM-DD."""
    raise NotImplementedError("weekly totals not written yet")


def main(path="sales.csv"):
    rows = load_rows(path)
    for month, total in sorted(totals_by_month(rows).items()):
        print(f"{month}  {total:>9.2f}")


if __name__ == "__main__":
    main()

