"""Turn a list of order dicts into text in one of several formats."""
import json


def export_csv_v1(orders):
    # Original format: semicolons, amount in cents.
    lines = ["id;customer;cents"]
    for o in orders:
        lines.append(f"{o['id']};{o['customer']};{int(round(o['amount'] * 100))}")
    return "\n".join(lines) + "\n"


def export_csv_v2(orders):
    lines = ["id,customer,amount"]
    for o in orders:
        lines.append(f"{o['id']},{o['customer']},{o['amount']:.2f}")
    return "\n".join(lines) + "\n"


def export_json_v1(orders):
    # Original JSON format: a bare list of [id, customer, amount].
    return json.dumps([[o["id"], o["customer"], o["amount"]] for o in orders])


def export_json_v2(orders):
    return json.dumps({"orders": orders}, sort_keys=True)


FORMATS = {
    "csv-v1": export_csv_v1,
    "csv-v2": export_csv_v2,
    "json-v1": export_json_v1,
    "json-v2": export_json_v2,
}


def export(orders, fmt="csv-v2"):
    try:
        func = FORMATS[fmt]
    except KeyError:
        raise ValueError(f"unknown format: {fmt}") from None
    return func(orders)

