"""Read the monthly supplier invoice export into dicts."""


def parse_line(line):
    return [field.strip() for field in line.split(",")]


def read_invoices(path):
    """Read the export: a standard CSV file, where fields containing commas are in double quotes."""
    with open(path, newline="") as fh:
        lines = [line.rstrip("\r\n") for line in fh if line.strip()]
    header = parse_line(lines[0])
    rows = []
    for line in lines[1:]:
        row = dict(zip(header, parse_line(line)))
        row["amount"] = float(row["amount"])
        rows.append(row)
    return rows


def total_by_supplier(rows):
    totals = {}
    for row in rows:
        totals[row["supplier"]] = round(totals.get(row["supplier"], 0) + row["amount"], 2)
    return totals

