"""Split catalogue search results into pages."""
import math

PER_PAGE = 10


def page_count(total, per_page=PER_PAGE):
    return max(1, math.ceil(total / per_page))


def get_page(items, page, per_page=PER_PAGE):
    """Items on `page`. Pages are numbered from 1, the same way the CLI shows them."""
    if page < 1 or page > page_count(len(items), per_page):
        raise ValueError(f"there is no page {page}")
    start = page * per_page
    return items[start:start + per_page]


def page_header(page, total, per_page=PER_PAGE):
    return f"Page {page} of {page_count(total, per_page)}"

