"""Monthly sales report: one line per month with that month's total."""
import csv


def monthly_totals(rows):
    """rows: (YYYY-MM-DD, amount) pairs. Returns {YYYY-MM: total} in month order."""
    totals = {}
    for day, amount in rows:
        totals[day[:7]] = totals.get(day[:7], 0.0) + amount
    return {month: round(totals[month], 2) for month in sorted(totals)}


def report_lines(rows):
    lines = ["month        total"]
    for month, total in monthly_totals(rows).items():
        lines.append(f"{month}  {total:>11.2f}")
    return lines


def print_report(path):
    with open(path, newline="") as fh:
        rows = [(r["date"], float(r["amount"])) for r in csv.DictReader(fh)]
    print("\n".join(report_lines(rows)))

