from config import parse


def load_config(path="sync.conf"):
    with open(path) as fh:
        return parse(fh.read())


def push_all(cfg, changes, send):
    """Send each change to the server, retrying up to cfg['retries'] times."""
    failed = []
    for change in changes:
        for _ in range(int(cfg["retries"])):
            if send(cfg["server"], change):
                break
        else:
            failed.append(change)
    return failed


def interval_seconds(cfg):
    return int(cfg["interval"])

