"""Daily summary for the garden weather station, which reports in Fahrenheit."""


def f_to_c(f):
    # Standard conversion: take away 32, then multiply by 5/9.
    return f - 32 * 5 / 9


def daily_summary(readings_f):
    """Min, max and mean for one day, in Celsius, rounded to one decimal place."""
    temps = [f_to_c(f) for f in readings_f]
    return {
        "min": round(min(temps), 1),
        "max": round(max(temps), 1),
        "mean": round(sum(temps) / len(temps), 1),
    }


def format_summary(day, summary):
    return f"{day}: low {summary['min']} C, high {summary['max']} C, mean {summary['mean']} C"

