"""List the files in a folder with their sizes, biggest first: python lsize.py FOLDER"""
import os
import sys


def format_size(n):
    return f"{n} B"


def list_sizes(folder):
    entries = []
    for name in sorted(os.listdir(folder)):
        path = os.path.join(folder, name)
        if os.path.isfile(path):
            entries.append((name, os.path.getsize(path)))
    entries.sort(key=lambda e: -e[1])
    return entries


def main(argv):
    folder = argv[0] if argv else "."
    for name, size in list_sizes(folder):
        print(f"{format_size(size):>12}  {name}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

