"""Sales by region for the quarterly review.

Rankings in this report always list the largest amount first; equal amounts are listed
alphabetically by name.
"""


def totals_by_region(sales):
    """sales: (region, amount) pairs, in the order they were recorded."""
    totals = {}
    for region, amount in sales:
        totals[region] = round(totals.get(region, 0) + amount, 2)
    return totals


def top_reps(sales_by_rep, n=3):
    ranked = sorted(sales_by_rep.items(), key=lambda kv: (-kv[1], kv[0]))
    return ranked[:n]


def region_table(sales):
    lines = []
    for region, total in totals_by_region(sales).items():
        lines.append(f"{region:<10}{total:>10.2f}")
    return lines

