"""Daily takings for the market stall, from the till's CSV export."""
import csv


def read_takings(path):
    """Return (day, amount) pairs in file order; amount is None when the cell is blank."""
    out = []
    with open(path, newline="") as fh:
        for row in csv.DictReader(fh):
            cell = row["takings"].strip()
            out.append((row["day"], float(cell) if cell else None))
    return out


def average_takings(days):
    return round(sum(a for _, a in days) / len(days), 2)


def best_day(days):
    return max(days, key=lambda d: d[1])
